args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

ASK WHERE {
  dbr:The_Lilac_Sunbonnet (dbo:country|dbp:country) ?c1 .
  OPTIONAL { ?c1 rdfs:label ?c1label FILTER(langMatches(lang(?c1label), "en")) }
  BIND( IF(bound(?c1label), lcase(str(?c1label)), lcase(str(?c1))) AS ?norm1 )

  dbr:The_Man_Without_Desire (dbo:country|dbp:country) ?c2 .
  OPTIONAL { ?c2 rdfs:label ?c2label FILTER(langMatches(lang(?c2label), "en")) }
  BIND( IF(bound(?c2label), lcase(str(?c2label)), lcase(str(?c2))) AS ?norm2 )

  FILTER(?norm1 = ?norm2)
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?country ?countryLabel WHERE {
  VALUES ?film { dbr:The_Lilac_Sunbonnet dbr:The_Man_Without_Desire }
  ?film (dbo:country|dbp:country) ?country .
  OPTIONAL { ?country rdfs:label ?countryLabel FILTER(langMatches(lang(?countryLabel), "en")) }
}

