    dbr:The_Man_Without_Desire dbo:country ?iri2 .
    ?iri2 rdfs:label ?lab2 FILTER(langMatches(lang(?lab2),"en")) .
    FILTER(str(?lit1) = str(?lab2))
  }
  UNION
  {
    dbr:The_Lilac_Sunbonnet dbo:country ?iri1 .
    dbr:The_Man_Without_Desire dbp:country ?lit2 .
    ?iri1 rdfs:label ?lab1 FILTER(langMatches(lang(?lab1),"en")) .
    FILTER(str(?lit2) = str(?lab1))
  }
  UNION
  {
    dbr:The_Lilac_Sunbonnet dbp:country ?lit1 .
    dbr:The_Man_Without_Desire dbp:country ?lit2 .
    FILTER(lcase(str(?lit1)) = lcase(str(?lit2)))
  }
  UNION
  {
    dbr:The_Lilac_Sunbonnet dbo:country ?iri1 .
    dbr:The_Man_Without_Desire dbo:country ?iri2 .
    FILTER(?iri1 = ?iri2)
  }
}

